  /// Accès à toutes les icônes (17730 icônes)
  static Map<String, IconEntry> get allIcons => _icons;

  /// Obtient une icône par son ID
  static IconEntry? getIconById(String id) => _icons[id];

  /// Vérifie si une icône existe
  static bool hasIcon(String id) => _icons.containsKey(id);

  /// Obtient toutes les icônes d'un set spécifique
  static List<IconEntry> getIconsBySet(String setName) {
    final prefix = setName.toLowerCase() + '_';
    return _icons.values.where((icon) => icon.id.startsWith(prefix)).toList();
  }

  /// Liste des sets d'icônes disponibles
  static List<String> get availableSets => [
    'antdesign',
    'bootstrap',
    'boxicons',
    'clarity',
    'evaicons',
    'fontawesome',
    'heroicons',
    'iconsax',
    'ionicons',
    'lineawesome',
    'mingcute',
    'octicons',
    'pixelarticons',
    'teenyicons',
    'zondicons',
  ];

  /// Recherche d'icônes avec filtrage et tri intelligent
  static List<IconEntry> searchIcons({
    required String query,
    String? category,
    String? style,
    String? setName,
    int limit = 50,
  }) {
    if (query.isEmpty) return [];

    final queryLower = query.toLowerCase();
    var results = _icons.values.where((icon) {
      // Filtrage par catégorie
      if (category != null && icon.category != category) return false;

      // Filtrage par style
      if (style != null && icon.style != style) return false;

      // Filtrage par set
      if (setName != null) {
        final prefix = setName.toLowerCase() + '_';
        if (!icon.id.startsWith(prefix)) return false;
      }

      // Recherche dans les métadonnées
      final searchableText = [
        icon.name,
        icon.category,
        ...icon.keywords,
        ...icon.tags,
      ].map((s) => s.toLowerCase()).join(' ');

      return searchableText.contains(queryLower);
    }).toList();

    // Tri par pertinence
    results.sort((a, b) {
      final aPriority = _getSearchPriority(a, queryLower);
      final bPriority = _getSearchPriority(b, queryLower);
      return bPriority.compareTo(aPriority);
    });

    return results.take(limit).toList();
  }

  /// Calcule la priorité de recherche pour le tri
  static int _getSearchPriority(IconEntry icon, String query) {
    // Correspondance exacte du nom = priorité maximale
    if (icon.name.toLowerCase() == query) return 1000;

    // Nom commence par la requête = haute priorité
    if (icon.name.toLowerCase().startsWith(query)) return 500;

    // Mot-clé exact = priorité moyenne
    if (icon.keywords.any((k) => k.toLowerCase() == query)) return 300;

    // Catégorie ou tag = priorité faible
    if (icon.category.toLowerCase() == query ||
        icon.tags.any((t) => t.toLowerCase() == query)) return 200;

    // Contient la requête = priorité minimale
    return 100;
  }

  /// Obtient toutes les icônes d'une catégorie
  static List<IconEntry> getIconsByCategory(String category) {
    return _icons.values.where((icon) => icon.category == category).toList();
  }

  /// Obtient la liste des catégories disponibles
  static List<String> get availableCategories {
    final categories = _icons.values.map((icon) => icon.category).toSet().toList();
    categories.sort();
    return categories;
  }

